from ios_strings_part1 import LANGS, T

# Gamification (Nutzerentscheidung 21.10.2026): Erfolge, Serie, Tagesziel, Abzeichen, Bestwerte, Wochenrückblick.
# Sprachen: en, de, ar, es, fr, it, ja, ko, nl, pl, pt-PT, ro, ru, tr, uk, zh-Hans


def P(key, forms):
    """Mengenformen je Sprache (`one`, `few`, `many`, `other`, …). Fehlende Formen = `other`; jede Form in allen 16."""
    cats = ["zero", "one", "two", "few", "many", "other"]
    out = {}
    for c in cats:
        if not any(c in forms[l] for l in LANGS):
            continue
        out[f"{key}#{c}"] = {l: forms[l].get(c, forms[l]["other"]) for l in LANGS}
    return out


